1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
3	const COMPONENT_BASE_PREMIUM = 25;
4	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
5	  sword: 100,
6	  amulet: 60,
7	  staff: 80,
8	  potion: 40,
9	  rune: COMPONENT_BASE_PREMIUM,
10	  moonstone: COMPONENT_BASE_PREMIUM,
11	};
12	const COMPONENT_BLOCK_SIZE = 3;
13	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
14	
15	type Item = {
16	  type: string;
17	  material?: string;
18	  enchantmentLevel?: number;
19	  cursed?: boolean;
20	};
21	
22	type Step = {
23	  op: string;
24	  items: Item[];
25	};
26	
27	type Scenario = {
28	  customer: { yearsWithMHPCO: number };
29	  steps: Step[];
30	};
31	
32	type QuoteResult = {
33	  premium: number;
34	};
35	
36	type ScenarioOutput = {
37	  results: QuoteResult[];
38	};
39	
40	const isComponentBlock = (items: Item[]): boolean =>
41	  items.length === COMPONENT_BLOCK_SIZE &&
42	  items.every((item) => item.type === items[0].type);
43	
44	const groupByType = (items: Item[]): Item[][] => {
45	  const groups = new Map<string, Item[]>();
46	  for (const item of items) {
47	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
48	  }
49	  return [...groups.values()];
50	};
51	
52	const basePremiumForGroup = (items: Item[]): number => {
53	  if (isComponentBlock(items)) return COMPONENT_BLOCK_BASE_PREMIUM;
54	  return items.reduce(
55	    (total, item) => total + BASE_PREMIUM_BY_ITEM_TYPE[item.type],
56	    0,
57	  );
58	};
59	
60	const basePremiumForItems = (items: Item[]): number =>
61	  groupByType(items).reduce(
62	    (total, group) => total + basePremiumForGroup(group),
63	    0,
64	  );
65	
66	const premiumBeforeProcessingFee = (items: Item[]): number => {
67	  const basePremium = basePremiumForItems(items);
68	  return basePremium + basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
69	};
70	
71	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
72	  results: scenario.steps.map((step) => ({
73	    premium: Math.ceil(premiumBeforeProcessingFee(step.items) + PROCESSING_FEE),
74	  })),
75	});
